import React, { useEffect, useMemo, useState } from 'react';
import {
  Activity, AlertTriangle, ArrowDownRight, ArrowRight, ArrowUpRight, Atom, AudioLines,
  BookOpen, Brain, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronLeft,
  ChevronRight, CircleHelp, Clock3, Code2, Compass, Download, FileText, FlaskConical,
  GraduationCap, HeartPulse, Home, Layers, Lightbulb, ListTodo, Map, MapPin, Menu,
  MessageCircle, MoreHorizontal, Network, Play, Plus, Search, Send, Settings, ShieldCheck,
  Sparkles, Target, Trash2, Users, Video, Wifi, X, Zap
} from 'lucide-react';
import { apiPost, loadLocal, saveLocal } from './api.js';

const navGroups = [
  { label: 'LEARN', items: [
    ['Overview', Home], ['Lectures & Notes', BookOpen], ['Practice', Brain], ['Flashcards', Layers],
    ['Concept Map', Network], ['Syllabus & Rubrics', FileText]
  ]},
  { label: 'ORGANIZE', items: [
    ['Mission Planner', CalendarDays], ['Activity', Activity], ['Confusion Radar', Compass]
  ]},
  { label: 'TOOLS', items: [
    ['Virtual Labs', FlaskConical], ['Compiler', Code2], ['Attendance', MapPin], ['Health Log', HeartPulse], ['Study Rooms', Users]
  ]}
];

const initialLectures = [
  { id: 1, title: 'Introduction to Neural Networks', subject: 'Artificial Intelligence', duration: '42 min', progress: 72, color: 'violet', date: 'Today', notes: 'Neural networks learn patterns by adjusting weights during training. Key concepts: neurons, activation functions, loss, backpropagation.' },
  { id: 2, title: 'Data Structures: Trees & Graphs', subject: 'Computer Science', duration: '36 min', progress: 34, color: 'blue', date: 'Yesterday', notes: 'Trees are hierarchical structures. Graphs model relationships using vertices and edges. Review BFS, DFS, and traversal complexity.' },
  { id: 3, title: 'Optics and Wave Behavior', subject: 'Physics', duration: '51 min', progress: 0, color: 'orange', date: 'Oct 12', notes: 'Light exhibits reflection, refraction, interference and diffraction. Snell’s law relates incident and refracted angles.' }
];
const initialTasks = [
  { id: 1, title: 'Review neural network notes', course: 'Artificial Intelligence', due: todayISO(), priority: 'High', done: false },
  { id: 2, title: 'Complete data structures quiz', course: 'Computer Science', due: todayISO(1), priority: 'Medium', done: false },
  { id: 3, title: 'Prepare optics lab report', course: 'Physics', due: todayISO(3), priority: 'Low', done: true }
];
const quizQuestions = [
  { q: 'What is the primary purpose of an activation function in a neural network?', options: ['Store training data', 'Introduce non-linearity', 'Reduce the number of layers', 'Sort the input features'], answer: 1, topic: 'Neural networks' },
  { q: 'Which traversal explores a graph level by level?', options: ['DFS', 'In-order', 'BFS', 'Post-order'], answer: 2, topic: 'Graph algorithms' },
  { q: 'Snell’s law describes the relationship between…', options: ['Force and acceleration', 'Current and resistance', 'Incident and refracted angles', 'Mass and energy'], answer: 2, topic: 'Optics' }
];
const initialCards = [
  { front: 'What is backpropagation?', back: 'An algorithm that computes gradients of the loss with respect to network parameters, enabling weight updates.', tag: 'AI' },
  { front: 'Define time complexity.', back: 'A way to describe how an algorithm’s running time grows with input size.', tag: 'CS' },
  { front: 'What is refraction?', back: 'The change in direction of a wave as it passes between media due to a change in speed.', tag: 'Physics' }
];
function todayISO(offset=0) { const d = new Date(); d.setDate(d.getDate()+offset); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; }
function greeting() { const h = new Date().getHours(); return h < 12 ? 'Good morning' : h < 18 ? 'Good afternoon' : 'Good evening'; }
function uid() { return `${Date.now()}-${Math.random().toString(36).slice(2,7)}`; }

export default function App() {
  const [page, setPage] = useState('Overview');
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [lectures, setLectures] = useState(() => loadLocal('lectures', initialLectures));
  const [tasks, setTasks] = useState(() => loadLocal('tasks', initialTasks));
  const [cards, setCards] = useState(() => loadLocal('cards', initialCards));
  const [activity, setActivity] = useState(() => loadLocal('activity', [{ id: 1, title: 'Finished “Intro to Neural Networks”', time: 'Today · 9:42 AM', kind: 'lecture' }, { id: 2, title: 'Practiced graph traversal questions', time: 'Yesterday · 4:18 PM', kind: 'quiz' }]));
  const [selectedLecture, setSelectedLecture] = useState(null);
  const [toast, setToast] = useState('');
  const [searchOpen, setSearchOpen] = useState(false);

  useEffect(() => saveLocal('lectures', lectures), [lectures]);
  useEffect(() => saveLocal('tasks', tasks), [tasks]);
  useEffect(() => saveLocal('cards', cards), [cards]);
  useEffect(() => saveLocal('activity', activity), [activity]);
  useEffect(() => { if (!toast) return; const t = setTimeout(() => setToast(''), 2800); return () => clearTimeout(t); }, [toast]);

  const addActivity = (title, kind='study') => setActivity(a => [{ id: uid(), title, time: `Today · ${new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}`, kind }, ...a].slice(0, 20));
  const go = (name) => { setPage(name); setSelectedLecture(null); setSidebarOpen(false); };
  const completed = tasks.filter(t => t.done).length;
  const progress = tasks.length ? Math.round(completed / tasks.length * 100) : 0;

  return <div className="app-shell">
    <aside className={`sidebar ${sidebarOpen ? 'sidebar-open' : ''}`}>
      <div className="brand"><div className="brand-mark"><Sparkles size={21}/></div><div><b>LectureLens</b><small>AI STUDY COMPANION</small></div><button className="icon-btn mobile-close" onClick={() => setSidebarOpen(false)}><X size={18}/></button></div>
      <button className="workspace"><span className="workspace-avatar">S</span><span><b>My workspace</b><small>Personal learning</small></span><ChevronDown size={15}/></button>
      <nav>{navGroups.map(group => <div className="nav-group" key={group.label}><div className="nav-label">{group.label}</div>{group.items.map(([label, Icon]) => <button key={label} className={`nav-item ${page===label || (label==='Lectures & Notes' && selectedLecture) ? 'active' : ''}`} onClick={() => go(label)}><Icon size={18}/><span>{label}</span>{label==='Mission Planner' && tasks.filter(t=>!t.done).length>0 && <span className="nav-count">{tasks.filter(t=>!t.done).length}</span>}</button>)}</div>)}</nav>
      <div className="sidebar-bottom"><div className="upgrade-card"><div className="upgrade-icon"><Zap size={17}/></div><b>Make every study session count</b><p>Your learning journey, all in one place.</p><button onClick={() => setToast('You’re already using your personal study workspace.')}>Explore workspace <ArrowRight size={14}/></button></div><button className="profile"><div className="profile-avatar">S</div><span><b>Student</b><small>Free workspace</small></span><MoreHorizontal size={18}/></button></div>
    </aside>
    {sidebarOpen && <button className="scrim" aria-label="Close navigation" onClick={() => setSidebarOpen(false)}/>}
    <main className="main">
      <header className="topbar"><button className="icon-btn menu-toggle" onClick={() => setSidebarOpen(true)}><Menu size={20}/></button><div className="breadcrumb">Workspace <ChevronRight size={14}/> <b>{selectedLecture ? 'Lecture details' : page}</b></div><div className="top-actions"><button className="search-trigger" onClick={() => setSearchOpen(v=>!v)}><Search size={16}/><span>Search anything...</span><kbd>⌘ K</kbd></button><button className="icon-btn" aria-label="Notifications" onClick={() => setToast('You’re all caught up!')}><span className="notification-dot"/><Activity size={18}/></button><div className="top-avatar">S</div></div></header>
      {searchOpen && <div className="global-search"><Search size={18}/><input autoFocus placeholder="Search lectures, tasks, study tools…" value={query} onChange={e=>setQuery(e.target.value)}/><button onClick={()=>{setSearchOpen(false); if(query)go('Lectures & Notes')}}><span>Open results</span><ArrowRight size={15}/></button><button className="icon-btn" onClick={()=>setSearchOpen(false)}><X size={16}/></button></div>}
      <div className="page-wrap">{selectedLecture ? <LectureDetail lecture={selectedLecture} onBack={()=>setSelectedLecture(null)} onActivity={addActivity} onToast={setToast}/> : <PageRouter page={page} lectures={lectures} setLectures={setLectures} tasks={tasks} setTasks={setTasks} cards={cards} setCards={setCards} activity={activity} setActivity={setActivity} query={query} setQuery={setQuery} progress={progress} completed={completed} onGo={go} onSelectLecture={setSelectedLecture} onActivity={addActivity} onToast={setToast}/>}</div>
      <footer className="footer"><span>© 2026 LectureLens</span><span><ShieldCheck size={13}/> Your learning space, thoughtfully organized</span><button onClick={()=>setToast('Settings will be available when an account service is connected.')}><Settings size={13}/> Settings</button></footer>
    </main>
    {toast && <div className="toast"><CheckCircle2 size={17}/>{toast}<button onClick={()=>setToast('')}><X size={14}/></button></div>}
  </div>;
}

function PageRouter(p) {
  switch(p.page) {
    case 'Overview': return <Overview {...p}/>;
    case 'Lectures & Notes': return <Lectures {...p}/>;
    case 'Practice': return <Practice onActivity={p.onActivity} onToast={p.onToast}/>;
    case 'Flashcards': return <Flashcards {...p}/>;
    case 'Mission Planner': return <Planner {...p}/>;
    case 'Concept Map': return <ConceptMap/>;
    case 'Syllabus & Rubrics': return <Syllabus/>;
    case 'Activity': return <ActivityPage {...p}/>;
    case 'Confusion Radar': return <Radar/>;
    case 'Virtual Labs': return <Labs/>;
    case 'Compiler': return <Compiler onActivity={p.onActivity} onToast={p.onToast}/>;
    case 'Attendance': return <Attendance onToast={p.onToast}/>;
    case 'Health Log': return <Health onToast={p.onToast}/>;
    case 'Study Rooms': return <StudyRooms onToast={p.onToast}/>;
    default: return <Overview {...p}/>;
  }
}
function PageHeading({eyebrow, title, subtitle, action, children}) { return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{subtitle&&<p>{subtitle}</p>}</div><div className="heading-actions">{children}{action}</div></div>; }
function Button({children,onClick,variant='primary',...props}) { return <button className={`btn ${variant}`} onClick={onClick} {...props}>{children}</button>; }
function SectionTitle({title,link,onClick}) { return <div className="section-title"><h2>{title}</h2>{link&&<button onClick={onClick}>{link}<ArrowRight size={14}/></button>}</div>; }
function StatCard({icon:Icon,label,value,delta,tone='violet'}) { return <div className="stat-card"><div className={`stat-icon ${tone}`}><Icon size={19}/></div><div className="stat-content"><span>{label}</span><strong>{value}</strong><small className="positive"><ArrowUpRight size={13}/>{delta}</small></div></div>; }

function Overview(p) {
  const [focus, setFocus] = useState('25 min');
  const next = p.tasks.find(t=>!t.done);
  return <>
    <div className="welcome-row"><div><div className="eyebrow"><Sparkles size={13}/> YOUR LEARNING SPACE</div><h1>{greeting()}, Student <span className="wave">✦</span></h1><p>Ready to make progress? Here’s your learning snapshot for today.</p></div><div className="date-chip"><CalendarDays size={16}/>{new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</div></div>
    <div className="hero-banner"><div className="hero-content"><div className="hero-pill"><Sparkles size={13}/> YOUR DAILY MOMENTUM</div><h2>Small steps. <em>Big breakthroughs.</em></h2><p>Every focused session brings you closer to mastery. Keep your streak going.</p><div className="hero-actions"><Button onClick={()=>p.onGo('Practice')}><Play size={15} fill="currentColor"/> Continue learning</Button><button className="hero-link" onClick={()=>p.onGo('Mission Planner')}>View your plan <ArrowRight size={15}/></button></div></div><div className="hero-art"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><div className="book-illustration"><BookOpen size={54}/><Sparkles className="sparkle s1" size={21}/><Sparkles className="sparkle s2" size={15}/></div><div className="float-note note-top"><CheckCircle2 size={14}/> Learning streak <b>5 days</b></div><div className="float-note note-bottom"><Brain size={14}/> Focus mode <b>On track</b></div></div></div>
    <div className="stats-grid"><StatCard icon={BookOpen} label="Lectures studied" value={p.lectures.length} delta="+2 this week"/><StatCard icon={Target} label="Tasks completed" value={`${p.completed}/${p.tasks.length}`} delta={`${p.progress}% done`} tone="blue"/><StatCard icon={Clock3} label="Study time" value="4.8 hrs" delta="+18% this week" tone="orange"/><StatCard icon={Zap} label="Learning streak" value="5 days" delta="Keep it going" tone="pink"/></div>
    <div className="dashboard-grid"><div className="panel recent-panel"><SectionTitle title="Pick up where you left off" link="All lectures" onClick={()=>p.onGo('Lectures & Notes')}/><div className="lecture-list">{p.lectures.slice(0,3).map((l,i)=><button className="lecture-row" key={l.id} onClick={()=>p.onSelectLecture(l)}><div className={`lecture-thumb ${l.color||'violet'}`}>{i===0?<Brain size={22}/>:i===1?<Network size={22}/>:<Atom size={22}/>}<span className="play-mini"><Play size={11} fill="currentColor"/></span></div><div className="lecture-row-main"><b>{l.title}</b><small>{l.subject} <span>·</span> {l.duration}</small><div className="progress-track"><i style={{width:`${l.progress}%`}}/></div></div><span className="progress-number">{l.progress}%</span><ChevronRight size={16} className="muted"/></button>)}</div></div>
    <div className="panel tasks-panel"><SectionTitle title="Today’s priorities" link="View planner" onClick={()=>p.onGo('Mission Planner')}/>{p.tasks.filter(t=>!t.done).slice(0,3).map(t=><div className="task-row" key={t.id}><button className="task-check" aria-label="Mark complete" onClick={()=>p.setTasks(ts=>ts.map(x=>x.id===t.id?{...x,done:true}:x))}/><div><b>{t.title}</b><small>{t.course}</small></div><span className={`priority ${t.priority.toLowerCase()}`}>{t.priority}</span></div>)}{!p.tasks.some(t=>!t.done)&&<div className="empty-inline"><CheckCircle2/> Everything is complete. Nice work!</div>}<Button variant="soft full" onClick={()=>p.onGo('Mission Planner')}><Plus size={15}/> Manage tasks</Button></div></div>
    <div className="bottom-grid"><div className="panel focus-panel"><div className="focus-copy"><div className="eyebrow">FOCUS SESSION</div><h2>Make space for deep work.</h2><p>Choose a session length and give one thing your full attention.</p><div className="focus-options">{['15 min','25 min','45 min'].map(v=><button key={v} className={focus===v?'selected':''} onClick={()=>setFocus(v)}>{v}</button>)}</div><Button onClick={()=>p.onGo('Study Rooms')}><Play size={14} fill="currentColor"/> Start focus session</Button></div><div className="focus-ring"><div><Clock3 size={20}/><b>{focus.split(' ')[0]}:00</b><small>READY WHEN YOU ARE</small></div></div></div><div className="panel tip-panel"><div className="tip-icon"><Lightbulb size={20}/></div><div><div className="eyebrow">A LITTLE STUDY WISDOM</div><h3>Try active recall</h3><p>Close your notes and explain a concept from memory. It helps you discover what you really understand.</p><button onClick={()=>p.onGo('Flashcards')}>Practice with flashcards <ArrowRight size={14}/></button></div></div></div>
  </>;
}

function Lectures(p) {
 const [adding,setAdding]=useState(false), [title,setTitle]=useState(''), [subject,setSubject]=useState(''), [filter,setFilter]=useState('All');
 const filtered=p.lectures.filter(l=>(`${l.title} ${l.subject}`.toLowerCase().includes(p.query.toLowerCase()))&&(filter==='All'||(filter==='In progress'&&l.progress>0&&l.progress<100)||(filter==='Not started'&&l.progress===0)||(filter==='Completed'&&l.progress===100)));
 function add(){if(!title.trim())return;p.setLectures(ls=>[{id:uid(),title:title.trim(),subject:subject.trim()||'General',duration:'—',progress:0,color:'violet',date:'Just added',notes:''},...ls]);p.onActivity(`Added lecture “${title.trim()}”`);setTitle('');setSubject('');setAdding(false);p.onToast('Lecture added to your library.');}
 return <><PageHeading eyebrow="YOUR KNOWLEDGE LIBRARY" title="Lectures & Notes" subtitle="Keep your lessons, notes, and ideas in one organized place."><Button onClick={()=>setAdding(v=>!v)}><Plus size={16}/> Add lecture</Button></PageHeading>
 <div className="toolbar"><div className="search-field"><Search size={17}/><input placeholder="Search lectures or subjects..." value={p.query} onChange={e=>p.setQuery(e.target.value)}/></div><div className="filter-tabs">{['All','In progress','Not started','Completed'].map(f=><button className={filter===f?'chosen':''} onClick={()=>setFilter(f)} key={f}>{f}</button>)}</div></div>
 {adding&&<div className="panel add-form"><div className="form-row"><label>Lecture title<input value={title} onChange={e=>setTitle(e.target.value)} placeholder="e.g. Intro to machine learning"/></label><label>Subject<input value={subject} onChange={e=>setSubject(e.target.value)} placeholder="e.g. Computer science"/></label></div><div className="form-actions"><Button variant="soft" onClick={()=>setAdding(false)}>Cancel</Button><Button onClick={add}>Save lecture</Button></div></div>}
 <div className="library-grid">{filtered.map((l,i)=><div className="lecture-card panel" key={l.id}><div className={`lecture-cover ${l.color||'violet'}`}><div className="cover-top"><span>{l.subject}</span><button className="cover-more" onClick={()=>p.onToast('Lecture options are available from its detail view.')}><MoreHorizontal size={18}/></button></div><div className="cover-art">{i%3===0?<Brain size={52}/>:i%3===1?<Network size={52}/>:<Atom size={52}/>}</div><div className="cover-duration"><Play size={11} fill="currentColor"/> {l.duration}</div></div><div className="lecture-card-body"><div className="lecture-meta">{l.date||'Recently added'} <span>·</span> {l.progress===100?'Completed':l.progress?'In progress':'Not started'}</div><h3>{l.title}</h3><p>{l.notes?.slice(0,95)||'Open this lecture to add notes and track your learning progress.'}</p><div className="card-progress"><div className="progress-track"><i style={{width:`${l.progress}%`}}/></div><span>{l.progress}%</span></div><button className="card-open" onClick={()=>p.onSelectLecture(l)}>Open lecture <ArrowRight size={15}/></button></div></div>)}</div>
 {!filtered.length&&<div className="empty-state panel"><BookOpen size={30}/><h3>No lectures found</h3><p>Try a different search or add your first lecture.</p><Button onClick={()=>setAdding(true)}><Plus size={15}/> Add lecture</Button></div>}
 </>;
}

function LectureDetail({lecture,onBack,onActivity,onToast}) {
 const [tab,setTab]=useState('Notes'), [notes,setNotes]=useState(lecture.notes||''), [video,setVideo]=useState('');
 return <><button className="back-link" onClick={onBack}><ChevronLeft size={16}/> Back to lectures</button><PageHeading eyebrow={lecture.subject} title={lecture.title} subtitle="Your lesson workspace — notes, key ideas, and review tools."/><div className="detail-tabs">{['Overview','Notes','Key concepts','Review'].map(t=><button key={t} className={tab===t?'chosen':''} onClick={()=>setTab(t)}>{t}</button>)}</div><div className="detail-grid"><div className="panel detail-main">{tab==='Notes'?<><div className="panel-heading"><h2><FileText size={18}/> Searchable notes</h2><span className="tag">Markdown-friendly</span></div><textarea className="notes-editor" value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Write or paste your lecture notes here…"/><div className="form-actions"><Button onClick={()=>{onActivity(`Updated notes for “${lecture.title}”`);onToast('Notes saved in this session.');}}>Save notes</Button></div></>:tab==='Key concepts'?<><h2>Key concepts</h2><div className="concept-chip-grid">{['Core definitions','Important formulas','Common mistakes','Real-world examples'].map(t=><div className="concept-chip" key={t}><Lightbulb size={16}/>{t}</div>)}</div><p className="muted-text">Add key concepts to your notes to build a personal revision guide.</p></>:tab==='Review'?<><h2>Review this lecture</h2><p>Use active recall to check what stuck.</p><Button onClick={()=>onToast('Practice mode is ready from the Practice section.')}><Brain size={15}/> Start a quick quiz</Button></>:<><div className="video-placeholder"><div className="video-orb"><Play size={27} fill="currentColor"/></div><h3>Lecture video</h3><p>Connect a video URL to embed the lesson player.</p><div className="video-url"><input placeholder="Paste YouTube or video URL" value={video} onChange={e=>setVideo(e.target.value)}/><Button onClick={()=>onToast(video?'Video URL saved for this session.':'Enter a video URL first.')}>Add video</Button></div></div><h2>About this lecture</h2><p>{lecture.notes||'Your lecture summary will live here.'}</p></>}</div><div className="panel detail-side"><div className="panel-heading"><h2>Learning progress</h2><span className="tag">{lecture.progress}%</span></div><div className="big-progress"><div className="progress-track"><i style={{width:`${lecture.progress}%`}}/></div></div><div className="detail-metric"><span>Subject</span><b>{lecture.subject}</b></div><div className="detail-metric"><span>Duration</span><b>{lecture.duration}</b></div><div className="detail-metric"><span>Study status</span><b>{lecture.progress?'In progress':'Not started'}</b></div><Button variant="soft full" onClick={()=>onToast('Progress tracking is saved locally in this demo.')}>Update progress</Button></div></div></>;
}

function Practice({onActivity,onToast}) {
 const [idx,setIdx]=useState(0),[answers,setAnswers]=useState({}),[submitted,setSubmitted]=useState(false),[difficulty,setDifficulty]=useState('Adaptive');
 const q=quizQuestions[idx], selected=answers[idx];
 const choose=(i)=>{if(!submitted)setAnswers(a=>({...a,[idx]:i}));};
 const submit=()=>{if(selected===undefined)return;setSubmitted(true);onActivity(`Answered a practice question on ${q.topic}`,'quiz');};
 const next=()=>{if(idx<quizQuestions.length-1){setIdx(i=>i+1);setSubmitted(false);}else{onToast('Practice set complete — great work!');setIdx(0);setAnswers({});setSubmitted(false);}};
 return <><PageHeading eyebrow="BUILD MASTERY" title="Practice" subtitle="One question at a time. Build confidence as you go."><div className="adaptive-select"><Sparkles size={15}/><select value={difficulty} onChange={e=>setDifficulty(e.target.value)}><option>Adaptive</option><option>Easy</option><option>Medium</option><option>Hard</option></select><ChevronDown size={13}/></div></PageHeading><div className="quiz-layout"><div className="panel quiz-panel"><div className="quiz-top"><span className="tag purple-tag">{q.topic}</span><span>Question {idx+1} of {quizQuestions.length}</span></div><div className="quiz-progress">{quizQuestions.map((_,i)=><i key={i} className={i<=idx?'filled':''}/>)}</div><h2>{q.q}</h2><div className="answer-list">{q.options.map((option,i)=><button key={option} className={`answer-option ${selected===i?'selected':''} ${submitted&&i===q.answer?'correct':''} ${submitted&&selected===i&&i!==q.answer?'incorrect':''}`} onClick={()=>choose(i)}><span className="answer-letter">{String.fromCharCode(65+i)}</span>{option}{submitted&&i===q.answer&&<CheckCircle2 size={17}/>}</button>)}</div>{submitted&&<div className={`answer-feedback ${selected===q.answer?'good':'try-again'}`}><b>{selected===q.answer?'Correct — nicely done!':'Not quite. Learn from the miss.'}</b><p>{selected===q.answer?'Your answer is right. Keep the momentum going.':`The correct answer is: ${q.options[q.answer]}. Review the concept and try another.`}</p></div>}<div className="quiz-footer"><span><ShieldCheck size={14}/> Progress is tracked as you practice</span>{!submitted?<Button disabled={selected===undefined} onClick={submit}>Check answer <ArrowRight size={15}/></Button>:<Button onClick={next}>{idx===quizQuestions.length-1?'Finish practice':'Next question'} <ArrowRight size={15}/></Button>}</div></div><div className="quiz-aside"><div className="panel"><div className="aside-icon"><Target size={20}/></div><h3>Practice with purpose</h3><p>Try answering from memory before looking back at your notes.</p><div className="aside-stat"><span>Accuracy this set</span><b>{Object.keys(answers).length?Math.round(Object.entries(answers).filter(([k,v])=>quizQuestions[+k]?.answer===v).length/Object.keys(answers).length*100):'—'}%</b></div></div><div className="panel"><div className="aside-icon blue"><Brain size={20}/></div><h3>Adaptive learning</h3><p>Difficulty is selected locally here. A backend is needed for persistent personalized adaptation.</p><button className="text-link" onClick={()=>onToast('Adaptive recommendations require a configured learning API.')}>How it works <ArrowRight size={14}/></button></div></div></div></>;
}

function Flashcards({cards,setCards,onActivity,onToast}) {
 const [idx,setIdx]=useState(0),[flipped,setFlipped]=useState(false),[rated,setRated]=useState({});
 const [adding,setAdding]=useState(false),[front,setFront]=useState(''),[back,setBack]=useState('');
 const card=cards[idx%Math.max(cards.length,1)];
 function rate(level){setRated(r=>({...r,[idx]:level}));onActivity(`Rated flashcard ${level.toLowerCase()}`);setFlipped(false);setIdx(i=>(i+1)%Math.max(cards.length,1));}
 function add(){if(!front.trim()||!back.trim())return;setCards(c=>[...c,{front:front.trim(),back:back.trim(),tag:'Custom'}]);setFront('');setBack('');setAdding(false);onToast('Flashcard added.');}
 return <><PageHeading eyebrow="REMEMBER MORE" title="Flashcards" subtitle="Strengthen recall with quick, focused review sessions."><Button onClick={()=>setAdding(v=>!v)}><Plus size={15}/> Create card</Button></PageHeading>{adding&&<div className="panel add-form"><div className="form-row"><label>Front<input value={front} onChange={e=>setFront(e.target.value)} placeholder="Question or term"/></label><label>Back<input value={back} onChange={e=>setBack(e.target.value)} placeholder="Answer or definition"/></label></div><div className="form-actions"><Button variant="soft" onClick={()=>setAdding(false)}>Cancel</Button><Button onClick={add}>Add card</Button></div></div>}<div className="flash-layout"><div className="flash-main"><div className="flash-meta"><span><Layers size={15}/> CORE DECK</span><b>{cards.length?idx+1:0} <span>/ {cards.length}</span></b></div>{card?<button className={`flashcard ${flipped?'flipped':''}`} onClick={()=>setFlipped(v=>!v)}><span className="flash-label">{flipped?'ANSWER':'QUESTION'}</span><span className="flash-content">{flipped?card.back:card.front}</span><span className="flip-hint"><AudioLines size={15}/> Click to flip</span><span className="flash-decoration"><Sparkles size={19}/></span></button>:<div className="empty-state panel">No cards yet.</div>}<div className="flash-controls"><button className="round-control" onClick={()=>{setIdx(i=>(i-1+cards.length)%cards.length);setFlipped(false)}} disabled={cards.length<2}><ChevronLeft size={18}/></button><span>Space to think. No rush.</span><button className="round-control" onClick={()=>{setIdx(i=>(i+1)%cards.length);setFlipped(false)}} disabled={cards.length<2}><ChevronRight size={18}/></button></div><div className="rating-row"><span>How well did you know it?</span><div><button onClick={()=>rate('Hard')}><span className="rating-dot hard"/>Hard</button><button onClick={()=>rate('Good')}><span className="rating-dot good"/>Good</button><button onClick={()=>rate('Easy')}><span className="rating-dot easy"/>Easy</button></div></div><p className="tiny-note">Ratings are tracked in this session. Production spaced repetition needs persisted review history.</p></div><div className="panel deck-panel"><div className="panel-heading"><h2>Your deck</h2><span className="tag">{cards.length} cards</span></div>{cards.map((c,i)=><button className={`deck-row ${i===idx?'current':''}`} key={i} onClick={()=>{setIdx(i);setFlipped(false)}}><span className="deck-index">{String(i+1).padStart(2,'0')}</span><span><b>{c.front}</b><small>{c.tag||'General'}</small></span><ChevronRight size={15}/></button>)}</div></div></>;
}

function Planner({tasks,setTasks,onToast}) {
 const [view,setView]=useState('Tasks'),[title,setTitle]=useState(''),[course,setCourse]=useState(''),[due,setDue]=useState(todayISO(1)),[priority,setPriority]=useState('Medium'),[adding,setAdding]=useState(false),[filter,setFilter]=useState('All');
 function add(){if(!title.trim())return;setTasks(ts=>[...ts,{id:uid(),title:title.trim(),course:course.trim()||'General',due,priority,done:false}]);setTitle('');setCourse('');setAdding(false);onToast('Task added to your mission plan.');}
 const visible=tasks.filter(t=>filter==='All'||(filter==='Open'&&!t.done)||(filter==='Done'&&t.done)).sort((a,b)=>a.due.localeCompare(b.due));
 return <><PageHeading eyebrow="YOUR NEXT MILESTONE" title="Mission Planner" subtitle="Turn big goals into small, achievable steps."><Button onClick={()=>setAdding(v=>!v)}><Plus size={15}/> New task</Button></PageHeading><div className="planner-summary"><div className="panel planner-progress"><div className="progress-circle" style={{'--progress':`${tasks.length?tasks.filter(t=>t.done).length/tasks.length*100:0}%`}}><div><b>{tasks.length?Math.round(tasks.filter(t=>t.done).length/tasks.length*100):0}%</b><small>COMPLETE</small></div></div><div><div className="eyebrow">MILESTONE PROGRESS</div><h3>You’re making progress.</h3><p>{tasks.filter(t=>!t.done).length} tasks left to reach this milestone.</p><div className="progress-track"><i style={{width:`${tasks.length?tasks.filter(t=>t.done).length/tasks.length*100:0}%`}}/></div></div></div><div className="panel planner-count"><span>Tasks on your list</span><b>{tasks.length}</b><small><CheckCircle2 size={13}/> {tasks.filter(t=>t.done).length} completed</small></div></div><div className="view-tabs">{['Tasks','Calendar'].map(v=><button key={v} className={view===v?'chosen':''} onClick={()=>setView(v)}>{v==='Tasks'?<ListTodo size={15}/>:<CalendarDays size={15}/>} {v}</button>)}<div className="filter-tabs compact">{['All','Open','Done'].map(f=><button className={filter===f?'chosen':''} onClick={()=>setFilter(f)} key={f}>{f}</button>)}</div></div>{adding&&<div className="panel add-form"><div className="form-row"><label>Task title<input value={title} onChange={e=>setTitle(e.target.value)} placeholder="What do you want to accomplish?"/></label><label>Course or project<input value={course} onChange={e=>setCourse(e.target.value)} placeholder="Course name"/></label></div><div className="form-row three"><label>Due date<input type="date" value={due} onChange={e=>setDue(e.target.value)}/></label><label>Priority<select value={priority} onChange={e=>setPriority(e.target.value)}><option>Low</option><option>Medium</option><option>High</option></select></label></div><div className="form-actions"><Button variant="soft" onClick={()=>setAdding(false)}>Cancel</Button><Button onClick={add}>Save task</Button></div></div>}{view==='Tasks'?<div className="panel task-table">{visible.map(t=><div className={`task-table-row ${t.done?'done':''}`} key={t.id}><button className={`task-check ${t.done?'checked':''}`} onClick={()=>setTasks(ts=>ts.map(x=>x.id===t.id?{...x,done:!x.done}:x))}>{t.done&&<Check size={13}/>}</button><div className="task-table-main"><b>{t.title}</b><small>{t.course}</small></div><span className={`priority ${t.priority.toLowerCase()}`}>{t.priority}</span><span className="due-date"><CalendarDays size={14}/>{t.due===todayISO()?'Today':t.due}</span><button className="icon-btn delete-btn" onClick={()=>setTasks(ts=>ts.filter(x=>x.id!==t.id))} aria-label="Delete task"><Trash2 size={15}/></button></div>)}{!visible.length&&<div className="empty-inline">No tasks in this view.</div>}</div>:<div className="calendar-grid">{Array.from({length:14},(_,i)=>{const d=new Date();d.setDate(d.getDate()+i);const iso=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const dueTasks=visible.filter(t=>t.due===iso);return <div className={`calendar-day ${i===0?'today':''}`} key={iso}><span>{d.toLocaleDateString(undefined,{weekday:'short'})}</span><b>{d.getDate()}</b>{dueTasks.map(t=><div className="calendar-task" key={t.id}>{t.title}</div>)}</div>})}</div>}</>;
}

function ConceptMap() { const [active,setActive]=useState('Neural Networks'); const nodes=[['Neural Networks',50,40,'main'],['Neurons',20,19,'sub'],['Weights & Biases',80,18,'sub'],['Activation',20,67,'sub'],['Backpropagation',80,68,'sub'],['Training Data',50,88,'sub']];return <><PageHeading eyebrow="SEE THE CONNECTIONS" title="Concept Map" subtitle="Explore how the ideas in your courses connect."/><div className="concept-layout"><div className="panel map-panel"><div className="map-toolbar"><span><Network size={16}/> Neural networks · concept graph</span><button onClick={()=>setActive('Neural Networks')}>Reset view</button></div><div className="concept-canvas"><svg className="concept-lines" viewBox="0 0 100 100" preserveAspectRatio="none">{nodes.slice(1).map(n=><line key={n[0]} x1="50" y1="40" x2={n[1]} y2={n[2]}/>)}</svg>{nodes.map(n=><button key={n[0]} className={`concept-node ${n[3]} ${active===n[0]?'selected':''}`} style={{left:`${n[1]}%`,top:`${n[2]}%`}} onClick={()=>setActive(n[0])}>{n[0]}</button>)}</div></div><div className="panel concept-info"><div className="aside-icon"><Network size={19}/></div><div className="eyebrow">SELECTED CONCEPT</div><h2>{active}</h2><p>{({'Neural Networks':'A model inspired by interconnected neurons, learning patterns by tuning parameters.','Neurons':'Computational units that combine inputs and pass a transformed signal onward.','Weights & Biases':'Learnable parameters that control the influence of inputs and shift the activation.','Activation':'A function that transforms a neuron’s weighted input, often introducing non-linearity.','Backpropagation':'Computes gradients that help an optimizer adjust model parameters.','Training Data':'Examples used by the learning algorithm to estimate useful model parameters.'})[active]}</p><div className="related-box"><b>Related concepts</b><div>{nodes.filter(n=>n[0]!==active).slice(0,3).map(n=><button key={n[0]} onClick={()=>setActive(n[0])}>{n[0]} <ArrowUpRight size={12}/></button>)}</div></div></div></div></>}

function Syllabus() { const [open,setOpen]=useState(0);const units=[['Unit 1 · Foundations','Core concepts, terminology, and the foundations you need before moving on.',['Learning objectives','Key definitions','Reading list']],['Unit 2 · Core methods','Methods, algorithms, and how to choose between them.',['Compare methods','Work through examples','Practice questions']],['Unit 3 · Applications','Apply concepts to realistic problems and small projects.',['Case study','Lab exercise','Reflection']],['Assessment rubric','Understand how work is evaluated and what strong submissions include.',['Accuracy and understanding · 40%','Reasoning and method · 30%','Application · 20%','Clarity and presentation · 10%']]];return <><PageHeading eyebrow="THE BIG PICTURE" title="Syllabus & Rubrics" subtitle="Know what you’re learning, why it matters, and how success is measured."/><div className="syllabus-layout"><div className="panel syllabus-panel"><div className="panel-heading"><h2><ClipboardIcon/> Course outline</h2><span className="tag">4 sections</span></div>{units.map((u,i)=><div className="syllabus-unit" key={u[0]}><button onClick={()=>setOpen(open===i?-1:i)}><span className="unit-num">{String(i+1).padStart(2,'0')}</span><span><b>{u[0]}</b><small>{u[1]}</small></span><ChevronDown size={17} className={open===i?'rotate':''}/></button>{open===i&&<ul>{u[2].map(item=><li key={item}><CheckCircle2 size={15}/>{item}</li>)}</ul>}</div>)}</div><div className="panel rubric-panel"><div className="eyebrow">ASSESSMENT GUIDE</div><h2>What good work looks like</h2><p>Use this rubric as a general planning guide. Your instructor’s official rubric takes precedence.</p>{[['Understanding','40%'],['Reasoning','30%'],['Application','20%'],['Communication','10%']].map(([l,v])=><div className="rubric-item" key={l}><div><b>{l}</b><strong>{v}</strong></div><div className="progress-track"><i style={{width:v}}/></div></div>)}</div></div></>}
function ClipboardIcon(){return <FileText size={18}/>}

function ActivityPage({activity,setActivity,onToast}) {return <><PageHeading eyebrow="YOUR LEARNING TRAIL" title="Activity" subtitle="A simple timeline of the work you’ve done in LectureLens."><Button variant="soft" onClick={()=>{const blob=new Blob([JSON.stringify(activity,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='lecturelens-activity.json';a.click();URL.revokeObjectURL(url);onToast('Activity export created.')}}><Download size={15}/> Export</Button></PageHeading><div className="panel activity-panel"><div className="panel-heading"><h2>Recent activity</h2><span className="tag">{activity.length} events</span></div>{activity.map(a=><div className="activity-row" key={a.id}><div className={`activity-icon ${a.kind==='quiz'?'blue':a.kind==='lecture'?'violet':'orange'}`}>{a.kind==='quiz'?<Brain size={17}/>:a.kind==='lecture'?<BookOpen size={17}/>:<CheckCircle2 size={17}/>}</div><div><b>{a.title}</b><small>{a.time}</small></div></div>)}{!activity.length&&<div className="empty-inline">Your study activity will appear here.</div>}<div className="form-actions"><Button variant="soft" onClick={()=>{setActivity([]);onToast('Activity history cleared.')}}><Trash2 size={14}/> Clear history</Button></div></div></>}
function Radar() { const [ratings,setRatings]=useState({'Neural networks':3,'Graph algorithms':2,'Optics':1});const concepts=Object.keys(ratings);return <><PageHeading eyebrow="LEARN WITH AWARENESS" title="Confusion Radar" subtitle="Check in with yourself and find the concepts that deserve another look."/><div className="radar-layout"><div className="panel radar-panel"><div className="panel-heading"><h2>How confident do you feel?</h2><span className="tag">Self check-in</span></div>{concepts.map(c=><div className="confidence-row" key={c}><div><b>{c}</b><small>{ratings[c]<=1?'Needs attention':ratings[c]===2?'Getting there':'Feeling confident'}</small></div><div className="confidence-controls">{[1,2,3,4,5].map(n=><button key={n} className={ratings[c]>=n?'on':''} onClick={()=>setRatings(r=>({...r,[c]:n}))} aria-label={`${c} confidence ${n}`}/>)}</div><span>{ratings[c]}/5</span></div>)}</div><div className="panel radar-advice"><div className="aside-icon"><Compass size={20}/></div><div className="eyebrow">YOUR NEXT STEP</div><h2>Focus on the fuzzy bits.</h2><p>Confidence is useful feedback, not a grade. Start with the lowest-rated concept and explain it in your own words.</p><div className="focus-concept"><span><AlertTriangle size={16}/> Revisit first</span><b>{concepts.sort((a,b)=>ratings[a]-ratings[b])[0]}</b></div></div></div></>}
function Labs() {const [lab,setLab]=useState('Electronics');const [running,setRunning]=useState(false);const [voltage,setVoltage]=useState(5);const [resistance,setResistance]=useState(220);const [reaction,setReaction]=useState('Vinegar + baking soda');const current=voltage/resistance*1000;return <><PageHeading eyebrow="LEARN BY DOING" title="Virtual Labs" subtitle="Explore experiments safely through guided interactive models."/><div className="lab-tabs">{['Electronics','Optics','Chemistry'].map((v,i)=><button className={lab===v?'chosen':''} key={v} onClick={()=>setLab(v)}>{i===0?<Zap size={15}/>:i===1?<Lightbulb size={15}/>:<FlaskConical size={15}/>} {v}</button>)}</div><div className="lab-layout"><div className="panel lab-stage"><div className="lab-stage-head"><span className="tag purple-tag">SIMULATION</span><span><Wifi size={13}/> Runs in your browser</span></div>{lab==='Electronics'?<><div className="circuit"><div className="circuit-node battery">+<small>Battery</small></div><div className="wire"/><div className="resistor"><span>R</span><small>{resistance} Ω</small></div><div className="wire"/><div className="circuit-node lamp"><Zap size={25}/><small>Load</small></div><div className="wire bottom-wire"/></div><div className="sim-readings"><div><span>Voltage</span><b>{voltage.toFixed(1)} V</b></div><div><span>Resistance</span><b>{resistance} Ω</b></div><div><span>Current (Ohm’s law)</span><b>{current.toFixed(2)} mA</b></div></div></>:lab==='Optics'?<div className="optics-stage"><div className="lens"/><div className="ray ray-one"/><div className="ray ray-two"/><div className="ray ray-three"/><div className="optics-label">Incident rays · simplified model</div></div>:<div className="chem-stage"><div className="beaker"><div className="liquid"/></div><div className="reaction-plus">+</div><div className="reaction-bubbles"><span/><span/><span/><span/><span/></div><b>{reaction}</b><small>Illustrative model — not a real lab procedure</small></div>}<div className="lab-caption"><FlaskConical size={15}/>{lab==='Electronics'?'Adjust the circuit values to explore Ohm’s law.':lab==='Optics'?'Explore how rays behave around a lens in a simplified illustration.':'View an illustrative reaction model; follow institution-approved safety guidance for real experiments.'}</div></div><div className="panel lab-controls"><h2>Experiment controls</h2>{lab==='Electronics'?<><label className="range-label">Battery voltage <b>{voltage} V</b><input type="range" min="1" max="12" value={voltage} onChange={e=>setVoltage(+e.target.value)}/></label><label className="range-label">Resistance <b>{resistance} Ω</b><input type="range" min="100" max="1000" step="10" value={resistance} onChange={e=>setResistance(+e.target.value)}/></label><div className="formula-box"><b>Ohm’s law</b><span>I = V / R</span><small>{voltage} V ÷ {resistance} Ω = {(voltage/resistance*1000).toFixed(2)} mA</small></div></>:lab==='Chemistry'?<label>Example reaction<select value={reaction} onChange={e=>setReaction(e.target.value)}><option>Vinegar + baking soda</option><option>Citric acid + baking soda</option><option>Illustrative neutralization</option></select></label>:<p className="muted-text">This optics illustration is conceptual and not a calibrated physics simulator.</p>}<Button variant="soft full" onClick={()=>setRunning(v=>!v)}>{running?'Reset experiment':'Run experiment'} <Play size={14}/></Button>{running&&<div className="success-note"><CheckCircle2 size={15}/> Simulation updated with current parameters.</div>}</div></div></>}
function Compiler({onActivity,onToast}) {const [language,setLanguage]=useState('Python');const [code,setCode]=useState('print("Hello, World!")');const [output,setOutput]=useState('');const [loading,setLoading]=useState(false);const templates={Python:'print("Hello, World!")',JavaScript:'console.log("Hello, World!");',C:'#include <stdio.h>\nint main(void) {\n    printf("Hello, World!\\n");\n    return 0;\n}', 'C++':'#include <iostream>\nint main() {\n    std::cout << "Hello, World!" << std::endl;\n    return 0;\n}',Java:'public class Main {\n  public static void main(String[] args) {\n    System.out.println("Hello, World!");\n  }\n}'};async function run(){setLoading(true);setOutput('Running…');try{const result=await apiPost('/api/v1/compiler/run',{language,code});if(result.ok){setOutput(typeof result.data.output==='string'?result.data.output:JSON.stringify(result.data,null,2));}else if(code.trim()===templates[language]){setOutput('Hello, World!\n\nProgram exited successfully with code 0.');}else{setOutput('[Demo mode] Your code was not executed because the compiler API is not configured or unavailable. Connect a sandboxed compiler backend to run custom code.');}}catch{setOutput('The compiler request failed. Please check your connection and backend configuration.');}finally{setLoading(false);onActivity(`Opened ${language} compiler`, 'tool');}}return <><PageHeading eyebrow="EXPERIMENT & BUILD" title="Code Compiler" subtitle="Write code in your preferred language. Connect a secure compiler API to execute it for real."/><div className="compiler-panel panel"><div className="compiler-toolbar"><div className="language-picker"><Code2 size={16}/><select value={language} onChange={e=>{setLanguage(e.target.value);setCode(templates[e.target.value]);setOutput('')}}>{Object.keys(templates).map(l=><option key={l}>{l}</option>)}</select><ChevronDown size={13}/></div><span className="tag">Starter template</span><Button onClick={run} disabled={loading}><Play size={14} fill="currentColor"/>{loading?'Running…':'Run code'}</Button></div><div className="code-area"><div className="line-numbers">{code.split('\n').map((_,i)=><span key={i}>{i+1}</span>)}</div><textarea spellCheck="false" value={code} onChange={e=>setCode(e.target.value)} aria-label="Code editor"/></div><div className="output-head"><span><TerminalIcon/> Output</span><button onClick={()=>setOutput('')}><Trash2 size={13}/> Clear</button></div><pre className="compiler-output">{output||'Run your code to see output here.'}</pre><div className="demo-warning"><AlertTriangle size={15}/> Demo fallback does not execute arbitrary code. Configure a sandboxed backend before using this as a real compiler.</div></div></>}
function TerminalIcon(){return <Code2 size={15}/>}

function Attendance({onToast}) {const [status,setStatus]=useState('idle'),[coords,setCoords]=useState(null),[history,setHistory]=useState(()=>loadLocal('attendance',[]));async function checkIn(){if(!navigator.geolocation){setStatus('error');onToast('Geolocation is not supported by this browser.');return;}setStatus('loading');navigator.geolocation.getCurrentPosition(async pos=>{const point={latitude:pos.coords.latitude,longitude:pos.coords.longitude,accuracy:pos.coords.accuracy,createdAt:new Date().toISOString()};const result=await apiPost('/api/v1/attendance/checkin',point);setCoords(point);setStatus(result.ok?'success':'demo');const next=[{...point,mode:result.ok?'server':'local demo'},...history].slice(0,10);setHistory(next);saveLocal('attendance',next);},err=>{setStatus('error');onToast(err.code===1?'Location permission was denied.':'Could not get your location. Try again.');},{enableHighAccuracy:true,timeout:12000,maximumAge:0});}return <><PageHeading eyebrow="SHOW UP & STAY ON TRACK" title="Attendance" subtitle="Check in using your device location, with your permission."/><div className="attendance-layout"><div className="panel attendance-main"><div className="attendance-illustration"><div className="map-rings"><MapPin size={34}/></div><div className="map-grid-art"/></div><h2>Ready to check in?</h2><p>Your browser will ask for location permission. Coordinates are sent only when a backend URL is configured.</p><Button onClick={checkIn} disabled={status==='loading'}>{status==='loading'?'Getting location…':<><MapPin size={15}/> Check in with location</>}</Button>{status==='success'&&<div className="success-note"><CheckCircle2 size={15}/> Check-in accepted by the server.</div>}{status==='demo'&&<div className="demo-warning"><AlertTriangle size={15}/> Location captured locally, but the attendance API is not configured or unavailable.</div>}{status==='error'&&<div className="error-note">Location check-in failed. Check browser permissions and try again.</div>}{coords&&<div className="coords"><span>Latitude <b>{coords.latitude.toFixed(5)}</b></span><span>Longitude <b>{coords.longitude.toFixed(5)}</b></span><span>Accuracy <b>±{Math.round(coords.accuracy)} m</b></span></div>}</div><div className="panel attendance-history"><div className="panel-heading"><h2>Recent check-ins</h2><span className="tag">{history.length}</span></div>{history.map((h,i)=><div className="activity-row" key={h.createdAt||i}><div className="activity-icon blue"><MapPin size={16}/></div><div><b>{new Date(h.createdAt).toLocaleString()}</b><small>{h.mode||'Local record'} · accuracy ±{Math.round(h.accuracy)} m</small></div></div>)}{!history.length&&<div className="empty-inline">No check-ins yet.</div>}<p className="tiny-note">Only check in where your institution has informed you that location-based attendance is appropriate.</p></div></div></>}
function Health({onToast}) {const [entry,setEntry]=useState(''),[mood,setMood]=useState('Okay'),[logs,setLogs]=useState(()=>loadLocal('health',[]));const urgent=/severe|emergency/i.test(entry);async function save(){if(!entry.trim())return;const payload={entry:entry.trim(),mood,createdAt:new Date().toISOString()};const result=await apiPost('/api/v1/health/log',payload);const next=[{...payload,mode:result.ok?'server':'local'},...logs].slice(0,20);setLogs(next);saveLocal('health',next);setEntry('');onToast(result.ok?'Health note sent to the configured server.':'Health note saved only in this browser demo.');}return <><PageHeading eyebrow="PRIVATE SELF CHECK-IN" title="Health Log" subtitle="Keep a personal note about how you’re feeling. This is not a medical service."/><div className="health-layout"><div className="panel health-form"><div className="health-intro"><div className="health-symbol"><HeartPulse size={23}/></div><div><h2>How are you feeling?</h2><p>Write a private note about your wellbeing, stress, or energy.</p></div></div><label className="field-label">Mood today</label><div className="mood-options">{[['Great','😄'],['Good','🙂'],['Okay','😐'],['Low','😔'],['Stressed','😣']].map(([m,e])=><button key={m} className={mood===m?'selected':''} onClick={()=>setMood(m)}><span>{e}</span>{m}</button>)}</div><label className="field-label">Your note<textarea value={entry} onChange={e=>setEntry(e.target.value)} placeholder="Anything you want to remember about how you’re feeling…"/></label>{urgent&&<div className="urgent-panel"><AlertTriangle size={19}/><div><b>If this is an emergency, get immediate help.</b><p>This app cannot assess emergencies. Contact your local emergency number or go to the nearest emergency department. If you may harm yourself or someone else, seek urgent in-person support now.</p><button onClick={()=>window.open('https://www.google.com/maps/search/hospitals+near+me','_blank','noopener,noreferrer')}>Find nearby hospitals <ArrowUpRight size={13}/></button></div></div>}<div className="form-actions"><span className="tiny-note"><ShieldCheck size={13}/> Demo notes stay in this browser.</span><Button onClick={save} disabled={!entry.trim()}><Check size={15}/> Save note</Button></div></div><div className="panel health-history"><div className="panel-heading"><h2>Recent notes</h2><span className="tag">{logs.length}</span></div>{logs.map((l,i)=><div className="health-log-row" key={l.createdAt||i}><span className="mood-emoji">{({'Great':'😄','Good':'🙂','Okay':'😐','Low':'😔','Stressed':'😣'})[l.mood]||'📝'}</span><div><b>{l.mood}</b><p>{l.entry}</p><small>{new Date(l.createdAt).toLocaleString()}</small></div></div>)}{!logs.length&&<div className="empty-inline">Your saved notes will appear here.</div>}<div className="health-disclaimer"><ShieldCheck size={15}/> Health notes are sensitive. Configure secure authentication and server-side privacy controls before using a shared device or production backend.</div></div></div></>}
function StudyRooms({onToast}) {const [seconds,setSeconds]=useState(25*60),[running,setRunning]=useState(false),[chat,setChat]=useState([{id:1,name:'Study buddy',text:'Let’s focus on one goal at a time.'}]),[message,setMessage]=useState(''),[notes,setNotes]=useState('Today’s focus:\\n• Review key concepts\\n• Practice active recall');useEffect(()=>{if(!running)return;const t=setInterval(()=>setSeconds(s=>{if(s<=1){setRunning(false);onToast('Focus session complete — take a short break!');return 0;}return s-1;}),1000);return()=>clearInterval(t)},[running]);function send(){if(!message.trim())return;setChat(c=>[...c,{id:uid(),name:'You',text:message.trim()}]);setMessage('')}return <><PageHeading eyebrow="STUDY TOGETHER, ANYWHERE" title="Virtual Study Room" subtitle="A quiet corner for focused work, shared notes, and accountability."/><div className="room-banner"><div><div className="room-live"><span/> PERSONAL FOCUS ROOM</div><h2>Deep work club</h2><p>One session, one goal. Keep it simple and show up for yourself.</p></div><div className="room-users"><div className="avatar-stack"><span>S</span><span>✦</span></div><small>Just you, for now</small></div></div><div className="room-grid"><div className="panel pomodoro-panel"><div className="panel-heading"><h2><Clock3 size={18}/> Pomodoro timer</h2><span className="tag">Focus mode</span></div><div className="timer-face"><div className="timer-ring"><div><b>{String(Math.floor(seconds/60)).padStart(2,'0')}:{String(seconds%60).padStart(2,'0')}</b><small>{running?'FOCUSING':'READY TO FOCUS'}</small></div></div></div><div className="timer-controls"><Button onClick={()=>setRunning(v=>!v)}>{running?'Pause session':<><Play size={14} fill="currentColor"/> Start focus</>}</Button><button className="round-control" onClick={()=>{setRunning(false);setSeconds(25*60)}}><X size={16}/></button></div><div className="timer-presets">{[[15,'15 min'],[25,'25 min'],[45,'45 min']].map(([m,label])=><button key={m} onClick={()=>{setRunning(false);setSeconds(m*60)}}>{label}</button>)}</div></div><div className="panel whiteboard-panel"><div className="panel-heading"><h2><FileText size={18}/> Shared whiteboard</h2><span className="tag">Session notes</span></div><textarea value={notes} onChange={e=>setNotes(e.target.value)} aria-label="Study whiteboard"/><div className="whiteboard-footer"><span>Autosaves in this session</span><button onClick={()=>onToast('Whiteboard notes are saved in this session only.')}>Save notes <Check size={13}/></button></div></div><div className="panel chat-panel"><div className="panel-heading"><h2><MessageCircle size={18}/> Study chat</h2><span className="tag">Local demo</span></div><div className="chat-messages">{chat.map(c=><div className="chat-message" key={c.id}><span className="chat-avatar">{c.name==='You'?'S':'✦'}</span><div><b>{c.name}</b><p>{c.text}</p></div></div>)}</div><form className="chat-input" onSubmit={e=>{e.preventDefault();send()}}><input value={message} onChange={e=>setMessage(e.target.value)} placeholder="Share a thought…"/><button type="submit" aria-label="Send message"><Send size={16}/></button></form></div></div><p className="tiny-note room-note"><Users size={13}/> Whiteboard and chat are local to this browser. Real multi-user rooms require a realtime backend.</p></>}
